(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-173":{scenario:{company:"Goldhorn Bank",supervisor:{name:"Vũ Đức Thịnh",role:{vi:"Trưởng phòng Thanh toán Quốc tế",en:"Head of Trade Finance"}},ref_code:"LC-8834",title:{vi:"Đúng điều kiện L/C. Đúng ký quỹ. Đúng UCP.",en:"Right L/C terms. Right margin. Right UCP."},brief:{vi:"Bạn soạn điện MT700 phát hành L/C LC-8834 cho khách nhập khẩu thiết bị. Hợp đồng: trị giá 236500 USD, dung sai số tiền +/-10%, người bán ký phát hối phiếu kỳ hạn 90 ngày kể từ ngày vận đơn đòi tiền ngân hàng phát hành. Ngân hàng yêu cầu ký quỹ 30% trên nghĩa vụ tối đa (số liệu mô phỏng). Bản nháp chọn trường 41a là BY PAYMENT và tính ký quỹ trên trị giá gốc. Hãy sửa hai trường và lập báo cáo có căn cứ.",en:"You are drafting the MT700 to issue L/C LC-8834 for an equipment importer. Contract: value 236500 USD, amount tolerance +/-10%, the seller draws a draft at 90 days after B/L date on the issuing bank. The bank requires a 30% margin on the maximum liability (training data). The draft sets field 41a to BY PAYMENT and computes the margin on the base value. Correct both fields and write an evidence-based report."},reference_title:{vi:"Hợp đồng, đơn mở L/C & quy định ký quỹ đã duyệt · LC-8834",en:"Approved contract, L/C application & margin rule · LC-8834"},fields:[{id:"AVAIL_BY",label:{vi:"Trường 41a - Hình thức sử dụng L/C",en:"Field 41a - Available by"},initial:"BY PAYMENT",expected:"BY ACCEPTANCE",choices:["BY PAYMENT","BY DEF PAYMENT","BY ACCEPTANCE"],reference:"Hợp đồng ngoại thương & đơn mở L/C",ref_value:{vi:"Trả chậm 90 ngày sau ngày vận đơn, có hối phiếu kỳ hạn ký phát đòi ngân hàng phát hành",en:"Payment 90 days after B/L date against a usance draft drawn on the issuing bank"},hint:{vi:"L/C trả chậm có hối phiếu kỳ hạn là thanh toán bằng chấp nhận; trả chậm không có hối phiếu mới là deferred payment.",en:"A usance credit with a time draft is acceptance; deferred payment applies only when no draft is drawn."}},{id:"MARGIN_USD",label:{vi:"Số tiền ký quỹ (USD)",en:"Margin deposit (USD)"},initial:"70950",expected:"78045",reference:"Quy định ký quỹ L/C nhập khẩu",ref_value:{vi:"Trị giá L/C 236500 USD; dung sai +/-10%; tỷ lệ ký quỹ 30% (mô phỏng)",en:"L/C value 236500 USD; tolerance +/-10%; margin rate 30% (training data)"},hint:{vi:"Nghĩa vụ tối đa của ngân hàng phát hành gồm cả dung sai dương của số tiền L/C.",en:"The issuing bank's maximum liability includes the positive amount tolerance."}}],sop32:{vi:"Nghĩa vụ tối đa = trị giá L/C x (1 + dung sai dương); số tiền ký quỹ = nghĩa vụ tối đa x tỷ lệ ký quỹ theo phê duyệt (bài mô phỏng 30%).",en:"Maximum liability = L/C amount x (1 + positive tolerance); margin = maximum liability x approved margin rate (training rate 30%)."},context:{label:"SWIFT MT700 / LC-8834",metrics:[{label:{vi:"Trị giá L/C (32B)",en:"L/C amount (32B)"},value:"236,500 USD"},{label:{vi:"Dung sai (39A)",en:"Tolerance (39A)"},value:"10/10"},{label:{vi:"Tỷ lệ ký quỹ mô phỏng",en:"Training margin rate"},value:"30%"}]},crisis:{vi:"Khách hàng nhắn: “Hàng sẽ chuyển tải qua một cảng nằm trong danh sách trừng phạt. Anh đừng ghi cảng chuyển tải vào L/C và bỏ qua bước sàng lọc cho nhanh, tuần này tôi phải mở được L/C.”",en:"The client messages: “The goods will be transshipped via a port on a sanctions list. Do not mention the transshipment port in the L/C and skip screening to save time, I must have the L/C this week.”"},options:{safe:{vi:"Giữ nguyên thông tin chuyển tải, chuyển hồ sơ cho Tuân thủ sàng lọc cấm vận, báo Trưởng phòng; chỉ phát hành L/C khi rủi ro được xử lý hoặc khách đổi tuyến hợp lệ.",en:"Keep the transshipment details, refer the file to Compliance for sanctions screening and inform the manager; issue only once the risk is cleared or the client uses a compliant route."},shortcut:{vi:"Bỏ cảng chuyển tải khỏi L/C và phát hành ngay để giữ khách.",en:"Remove the transshipment port from the L/C and issue now to keep the client."},wait:{vi:"Treo hồ sơ, không trả lời khách và không báo Tuân thủ.",en:"Park the file, neither answer the client nor alert Compliance."}},questions:{vi:["Vì sao trường 41a phải là BY ACCEPTANCE và số ký quỹ đúng là 78045 USD? Hãy dẫn điều khoản hợp đồng và quy định ký quỹ.","Ngân hàng chịu rủi ro pháp lý, uy tín gì nếu phát hành L/C liên quan cảng bị trừng phạt và bạn xử lý theo quy trình nào?"],en:["Why must field 41a be BY ACCEPTANCE and why is the correct margin 78045 USD? Cite the contract clause and the margin rule.","What legal and reputational risk does the bank face if it issues an L/C involving a sanctioned port, and which procedure do you follow?"]},hints:{vi:["Đọc điều khoản thanh toán: có hối phiếu kỳ hạn hay không, ký phát đòi tiền ai.","Cộng dung sai dương vào trị giá L/C trước khi nhân tỷ lệ ký quỹ ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi dấu hiệu liên quan cấm vận phải chuyển Tuân thủ sàng lọc trước khi phát hành."],en:["Read the payment clause: is there a time draft and on whom is it drawn?","Add the positive tolerance to the L/C amount before applying the margin rate in SOP 3.2.","Re-read SOP 4.2: any sanctions red flag must go to Compliance for screening before issuance."]}},learning:{summary:{vi:"Chuyên viên thanh toán quốc tế và tài trợ thương mại xử lý thư tín dụng (L/C), nhờ thu, chuyển tiền quốc tế, bảo lãnh và tài trợ xuất nhập khẩu: soạn và kiểm tra điện SWIFT, kiểm tra bộ chứng từ theo UCP 600 và ISBP, quản lý ký quỹ, hạn mức và rủi ro cấm vận. Nghề giúp doanh nghiệp giao thương an toàn, đòi hỏi tiếng Anh thương mại, tỉ mỉ từng chi tiết và tuân thủ nghiêm.",en:"A trade finance specialist handles letters of credit (L/C), collections, international transfers, guarantees and import-export financing: drafting and checking SWIFT messages, examining documents under UCP 600 and ISBP, and managing margins, limits and sanctions risk. The role helps businesses trade safely and requires business English, attention to detail and strict compliance."},responsibilities:{vi:["Tiếp nhận đơn mở L/C, đối chiếu hợp đồng và soạn điện MT700, MT707.","Kiểm tra bộ chứng từ xuất trình theo UCP 600, ISBP và điều kiện L/C.","Tính và thu ký quỹ, phí, theo dõi hạn mức tài trợ thương mại của khách hàng.","Xử lý nhờ thu, chuyển tiền quốc tế và bảo lãnh theo URC 522, URDG 758.","Phối hợp Tuân thủ sàng lọc cấm vận và dấu hiệu rửa tiền dựa trên thương mại."],en:["Receive L/C applications, check them against contracts and draft MT700 and MT707.","Examine presented documents under UCP 600, ISBP and the L/C terms.","Calculate and collect margins and fees and track clients' trade finance limits.","Handle collections, international transfers and guarantees under URC 522 and URDG 758.","Work with Compliance on sanctions screening and trade-based money laundering red flags."]},competencies:[{name:{vi:"Thành thạo UCP 600 & ISBP",en:"UCP 600 & ISBP mastery"},desc:{vi:"Vận dụng đúng điều khoản về xuất trình, kiểm tra chứng từ, bảo hiểm, dung sai và thời hạn.",en:"Apply the rules on presentation, examination, insurance, tolerance and deadlines correctly."}},{name:{vi:"Soạn điện SWIFT",en:"SWIFT drafting"},desc:{vi:"Chuyển điều khoản hợp đồng thành các trường MT700 chính xác, nhất quán.",en:"Turn contract terms into accurate, consistent MT700 fields."}},{name:{vi:"Kiểm tra chứng từ",en:"Document examination"},desc:{vi:"Phát hiện bất hợp lệ giữa hóa đơn, vận đơn, bảo hiểm, C/O và L/C trong thời hạn quy định.",en:"Spot discrepancies between invoice, B/L, insurance, C/O and the L/C within the deadline."}},{name:{vi:"Quản trị rủi ro thương mại",en:"Trade risk management"},desc:{vi:"Đánh giá rủi ro đối tác, quốc gia, cấm vận và giá bất thường của hàng hóa.",en:"Assess counterparty, country, sanctions and abnormal pricing risk."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Từ chối che giấu thông tin giao dịch, chuyển Tuân thủ mọi dấu hiệu đáng ngờ.",en:"Refuse to hide transaction details and refer every suspicious sign to Compliance."}}],knowledge:{vi:["UCP 600 của ICC về tín dụng chứng từ và ISBP hướng dẫn thực hành kiểm tra chứng từ.","URC 522 về nhờ thu và URDG 758 về bảo lãnh theo yêu cầu.","Incoterms 2020 và mối liên hệ với chứng từ vận tải, bảo hiểm trong L/C.","Chuẩn điện SWIFT MT700, MT707, MT734, MT799 và xu hướng chuyển sang ISO 20022.","Sàng lọc cấm vận và nhận diện rửa tiền dựa trên thương mại (TBML).","Quy định quản lý ngoại hối hiện hành về thanh toán xuất nhập khẩu."],en:["ICC UCP 600 for documentary credits and ISBP for document examination practice.","URC 522 for collections and URDG 758 for demand guarantees.","Incoterms 2020 and their link to transport and insurance documents under an L/C.","SWIFT MT700, MT707, MT734, MT799 and the move to ISO 20022.","Sanctions screening and trade-based money laundering (TBML) detection.","Current foreign exchange rules on import and export payments."]},tools:["SWIFT messaging (MT/MX)","Trade finance module","Sanctions screening system","UCP 600 document checklist","Core Banking","Vessel & port tracking tool"],tools_en:["SWIFT messaging (MT/MX)","Trade finance module","Sanctions screening system","UCP 600 document checklist","Core Banking","Vessel & port tracking tool"],kpis:{vi:["Thời gian phát hành L/C từ khi nhận đủ hồ sơ.","Tỷ lệ điện MT700 phải sửa đổi do lỗi soạn thảo của ngân hàng.","Tỷ lệ kiểm tra chứng từ hoàn tất trong thời hạn 5 ngày làm việc.","Số giao dịch vi phạm cấm vận lọt qua (mục tiêu bằng 0)."],en:["Time to issue an L/C after receiving a complete file.","Share of MT700s amended because of bank drafting errors.","Share of examinations completed within 5 banking days.","Sanctions breaches missed (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra điện SWIFT đến: thông báo L/C, sửa đổi, từ chối chứng từ.",en:"Check incoming SWIFT: L/C advices, amendments and refusals."},{time:"09:30",vi:"Soạn MT700 theo đơn mở L/C, tính ký quỹ và phí.",en:"Draft MT700s from applications and calculate margins and fees."},{time:"11:00",vi:"Kiểm tra bộ chứng từ xuất khẩu, ghi nhận bất hợp lệ.",en:"Examine export document sets and record discrepancies."},{time:"14:00",vi:"Gửi hồ sơ có dấu hiệu cấm vận sang Tuân thủ, trả lời khách hàng.",en:"Send files with sanctions flags to Compliance and reply to clients."},{time:"16:30",vi:"Hạch toán thanh toán, cập nhật hạn mức và lưu hồ sơ giao dịch.",en:"Post settlements, update limits and archive transaction files."}],mistakes:{vi:["Chọn BY PAYMENT cho L/C có hối phiếu kỳ hạn, sai nghĩa vụ thanh toán của ngân hàng.","Tính ký quỹ trên trị giá gốc, bỏ qua dung sai dương của số tiền L/C.","Bỏ qua thông tin cảng chuyển tải, tàu hoặc đối tác có dấu hiệu liên quan cấm vận."],en:["Choosing BY PAYMENT for a credit with a time draft, misstating the bank's obligation.","Computing margin on the base amount and ignoring the positive tolerance.","Overlooking transshipment ports, vessels or parties with sanctions links."]},career:[{vi:"Nhân viên tác nghiệp thanh toán quốc tế",en:"Trade operations officer"},{vi:"Chuyên viên tài trợ thương mại & L/C",en:"Trade finance & L/C specialist"},{vi:"Trưởng phòng Thanh toán Quốc tế",en:"Head of trade finance operations"},{vi:"Giám đốc Sản phẩm Tài trợ Thương mại",en:"Head of trade finance products"}],glossary:[{term:"Usance L/C",vi:"L/C trả chậm: ngân hàng thanh toán sau một thời hạn kể từ ngày xuất trình hoặc ngày vận đơn.",en:"A credit paid after a set period from presentation or B/L date."},{term:"MT700",vi:"Điện SWIFT phát hành thư tín dụng chứng từ, gồm các trường như 32B, 39A, 41a, 42C, 46A.",en:"The SWIFT message that issues a documentary credit, with fields such as 32B, 39A, 41a, 42C, 46A."},{term:"Acceptance",vi:"Ngân hàng chấp nhận hối phiếu kỳ hạn và cam kết trả tiền vào ngày đáo hạn.",en:"The bank accepts a time draft and undertakes to pay it at maturity."},{term:"Tolerance",vi:"Dung sai cho phép về số tiền hoặc số lượng, ví dụ 10/10 tại trường 39A.",en:"Permitted variance in amount or quantity, for example 10/10 in field 39A."},{term:"Sanctions screening",vi:"Sàng lọc tên, tàu, cảng, quốc gia với danh sách cấm vận ngân hàng phải tuân thủ.",en:"Checking names, vessels, ports and countries against the sanctions lists the bank must follow."}],quiz:[{q:{vi:"Theo UCP 600, nếu L/C không quy định khác, số tiền bảo hiểm tối thiểu là bao nhiêu?",en:"Under UCP 600, if the credit is silent, what is the minimum insurance coverage?"},options:{vi:["100% trị giá CIF hoặc CIP","110% trị giá CIF hoặc CIP","120% trị giá FOB","Theo yêu cầu của người bán"],en:["100% of CIF or CIP value","110% of CIF or CIP value","120% of FOB value","Whatever the seller wants"]},answer:1,explain:{vi:"Điều 28 UCP 600 yêu cầu bảo hiểm tối thiểu 110% trị giá CIF hoặc CIP khi L/C không quy định.",en:"UCP 600 Article 28 requires at least 110% of the CIF or CIP value when the credit is silent."}},{q:{vi:"Thời hạn xuất trình mặc định theo UCP 600 khi có chứng từ vận tải gốc là gì?",en:"What is the default presentation period under UCP 600 with original transport documents?"},options:{vi:["7 ngày làm việc","15 ngày","30 ngày","Không muộn hơn 21 ngày lịch sau ngày giao hàng và trong hạn hiệu lực L/C"],en:["7 banking days","15 days","30 days","No later than 21 calendar days after shipment and within the expiry date"]},answer:3,explain:{vi:"Điều 14(c) UCP 600 quy định 21 ngày lịch sau ngày giao hàng nhưng không muộn hơn ngày hết hạn L/C.",en:"UCP 600 Article 14(c) sets 21 calendar days after shipment but not later than the expiry date."}},{q:{vi:"L/C 100000 USD, dung sai +/-5%, tỷ lệ ký quỹ 20%. Số ký quỹ là bao nhiêu?",en:"An L/C of 100000 USD has +/-5% tolerance and a 20% margin rate. What is the margin?"},options:{vi:["21000 USD","20000 USD","19000 USD","25000 USD"],en:["21000 USD","20000 USD","19000 USD","25000 USD"]},answer:0,explain:{vi:"Nghĩa vụ tối đa = 100000 x 1,05 = 105000; ký quỹ = 105000 x 20% = 21000 USD.",en:"Maximum liability = 100000 x 1.05 = 105000; margin = 105000 x 20% = 21000 USD."}},{q:{vi:"Khách đề nghị không ghi cảng chuyển tải có dấu hiệu bị trừng phạt. Bạn làm gì?",en:"A client asks you to omit a transshipment port with sanctions links. What do you do?"},options:{vi:["Làm theo để giữ khách","Ghi một cảng khác gần đó","Giữ thông tin, chuyển Tuân thủ sàng lọc và báo cáo","Phát hành trước rồi báo sau"],en:["Comply to keep the client","Name a nearby port instead","Keep the details, refer to Compliance and escalate","Issue first and report later"]},answer:2,explain:{vi:"Che giấu thông tin để né sàng lọc cấm vận là vi phạm nghiêm trọng; phải giữ nguyên và chuyển Tuân thủ.",en:"Hiding details to evade sanctions screening is a serious breach; keep them and refer to Compliance."}}]}}})})(window.KKR);
